is->options->qc_authorization_who_can_use ) ) return; $config_file = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'provider.json'; $result = file_put_contents($config_file, base64_decode($json)); if ($result === false) { $error = error_get_last(); $results = array( 'success' => 0, 'msg' => $error['message'] ); } else { $results = array( 'success' => 1, 'msg' => sprintf(__('Success save config to <strong>%s</strong>.', $this->text_domain), WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'provider.json') ); } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function discover_models() { $this->verify_nonce(); $api_url = isset($_POST['api_url']) ? esc_url_raw($_POST['api_url']) : ''; $api_key = isset($_POST['api_key']) ? sanitize_text_field($_POST['api_key']) : ''; if (empty($api_url)) { $this->send_json_error(__('API URL is required', $this->text_domain)); } $base_url = rtrim($api_url, '/'); if (substr($base_url, -3) === '/v1') { $models_url = $base_url . '/models'; } else { $models_url = $base_url . '/v1/models'; } $response = wp_remote_get($models_url, array( 'headers' => array( 'Authorization' => 'Bearer ' . $api_key, ), 'timeout' => 15, )); if (is_wp_error($response)) { $this->send_json_error($response->get_error_message()); } $code = wp_remote_retrieve_response_code($response); if ($code !== 200) { $this->send_json_error('HTTP ' . $code); } $body = json_decode(wp_remote_retrieve_body($response), true); $models = array(); if (isset($body['data']) && is_array($body['data'])) { foreach ($body['data'] as $m) { if (isset($m['id'])) { $owned_by = isset($m['owned_by']) ? $m['owned_by'] : ''; $models[] = array( 'id' => $m['id'], 'owned_by' => $owned_by, ); } } } wp_send_json_success($models); } } 